import * as React from "react";
import { AppBar, Toolbar, Typography, Box, Button, IconButton } from "@mui/material";
import ShoppingCartIcon from "@mui/icons-material/ShoppingCart";
// @ts-ignore
import SwipeableViews from "react-swipeable-views";

import HomePage from "./HomePage";
import VenuesPage from "./VenuesPage";
import HairPage from "./HairPage";
import MakeupPage from "./MakeupPage";
import PhotographersPage from "./PhotographersPage";
import MusicPage from "./MusicPage";
import FloristPage from "./FloristPage";
import DresserPage from "./DresserPage";
import PlannerPage from "./PlannerPage";
import HomeIcon from "@mui/icons-material/Home";
import SearchIcon from "@mui/icons-material/Search";
import MessageIcon from "@mui/icons-material/Message";
import PersonIcon from "@mui/icons-material/Person";

interface NavigationBarProps {
  onSelect?: (page: string) => void;
}

export default function NavigationBar({ onSelect }: NavigationBarProps) {
  const [activePage, setActivePage] = React.useState(0);

  const menuItems = [
    { label: "Home", value: "home", component: <HomePage /> },
    { label: "Venues", value: "venues", component: <VenuesPage /> },
    { label: "Hair", value: "hair", component: <HairPage /> },
    { label: "Makeup", value: "makeup", component: <MakeupPage /> },
    { label: "Photographers", value: "photographers", component: <PhotographersPage /> },
    { label: "Music", value: "music", component: <MusicPage /> },
    { label: "Florist", value: "florist", component: <FloristPage /> },
    { label: "Dresser", value: "dresser", component: <DresserPage /> },
    { label: "Planner", value: "planner", component: <PlannerPage /> },
  ];

  const handleMenuItemClick = (index: number) => {
    setActivePage(index);
    if (onSelect) {
      onSelect(menuItems[index].value);
    }
  };

  return (
    <>
      <AppBar
        position="sticky"
        color="default"
        elevation={1}
        sx={{
          backgroundColor: "#fff",
          top: 0,
          zIndex: 1200,
        }}
      >
        <Toolbar sx={{ display: "flex", alignItems: "center", paddingX: 4 }}>
          <Typography
            variant="h6"
            sx={{
              fontWeight: "bold",
              textTransform: "uppercase",
              cursor: "pointer",
              flexGrow: 1,
              textAlign: "center",
            }}
            onClick={() => handleMenuItemClick(0)}
          >
            Logo Placeholder
          </Typography>
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <IconButton color="inherit">
              <ShoppingCartIcon sx={{ fontSize: "28px", color: "#000" }} />
            </IconButton>
          </Box>
        </Toolbar>
           <SwipeableViews
        index={activePage}
        onChangeIndex={setActivePage}
        enableMouseEvents
        resistance
        style={{ width: "100%", height: "100vh" }}
        slideStyle={{ width: "100%" }}
      >
        {/*{menuItems.map((item) => (*/}
        {/*  <Box*/}
        {/*    key={item.value}*/}
        {/*    sx={{*/}
        {/*      width: "100%",*/}
        {/*      height: "calc(100vh - 64px)",*/}
        {/*      display: "flex",*/}
        {/*      flexDirection: "column",*/}
        {/*      overflow: "hidden",*/}
        {/*      touchAction: "pan-y",*/}
        {/*    }}*/}
        {/*  >*/}
        {/*    {item.component}*/}
        {/*  </Box>*/}
        {/*))}*/}

        <Box
          sx={{
            display: "flex",
            overflowX: "auto",
            flexGrow: 1,
            justifyContent: "flex-start",
            paddingX: 2,
            width: "100%",
            flexWrap: "nowrap",
            "&::-webkit-scrollbar": { display: "none" },
          }}
        >
          {menuItems.map((item, index) => (
            <Button
              key={item.value}
              color="inherit"
              sx={{
                textTransform: "uppercase",
                fontWeight: 500,
                fontSize: "14px",
                paddingX: 2,
                minWidth: "max-content",
                borderBottom: activePage === index ? "2px solid black" : "none",
                transition: "border-bottom 0.3s ease-in-out",
              }}
              onClick={() => handleMenuItemClick(index)}
            >
              {item.label}
            </Button>
          ))}
        </Box>
     </SwipeableViews>
      </AppBar>


       {/* Bottom Navigation Bar */}
       <AppBar
        position="fixed"
        sx={{
          top: "auto",
          bottom: 0,
          left: 0,
          right: 0,
          backgroundColor: "transparent",
          boxShadow: "none",
          zIndex: 1300,
          padding: "10px 0",
        }}
      >
        <Toolbar sx={{ display: "flex", justifyContent: "space-around", paddingX: 0 }}>
           <IconButton sx={{ color: "#000" }}>
             <SearchIcon />
           </IconButton>
           <IconButton sx={{ color: "#000" }}>
             <HomeIcon />
           </IconButton>
           <IconButton sx={{ color: "#000" }}>
             <MessageIcon />
           </IconButton>
           <IconButton sx={{ color: "#000" }}>
             <PersonIcon />
           </IconButton>
        </Toolbar>
      </AppBar>
    </>
  );
}



